css:
.tl { width: 300px; }
.tl-bar { height: 14px; margin-bottom: 12px; border-radius: 6px; }
.tl-w100 { width: 100%; } .tl-w90 { width: 90%; } .tl-w75 { width: 75%; } .tl-w50 { width: 50%; }
.tl-bar { background: linear-gradient(90deg, #e5e7eb 25%, #f3f4f6 37%, #e5e7eb 63%); background-size: 400% 100%; animation: tl-bar-shimmer 1.4s ease infinite; }
@keyframes tl-bar-shimmer { 0% { background-position: 100% 50%; } 100% { background-position: 0 50%; } }

.av { display: flex; align-items: center; gap: 14px; width: 300px; }
.av-pic { flex: none; width: 52px; height: 52px; border-radius: 50%; }
.av-lines { flex: 1; }
.av-line { height: 12px; border-radius: 6px; }
.av-name { width: 60%; margin-bottom: 10px; }
.av-sub { width: 90%; }
.av-pic, .av-line { background: linear-gradient(90deg, #e5e7eb 25%, #f3f4f6 37%, #e5e7eb 63%); background-size: 400% 100%; animation: av-shimmer 1.4s ease infinite; }
@keyframes av-shimmer { 0% { background-position: 100% 50%; } 100% { background-position: 0 50%; } }

.cd { width: 260px; overflow: hidden; background: #fff; border: 1px solid #e5e7eb; border-radius: 12px; }
.cd-img { height: 120px; }
.cd-body { padding: 14px; }
.cd-line { height: 11px; margin-bottom: 9px; border-radius: 6px; }
.cd-title { width: 70%; height: 15px; margin-bottom: 14px; }
.cd-short { width: 45%; }
.cd-img, .cd-line { background: linear-gradient(90deg, #e5e7eb 25%, #f3f4f6 37%, #e5e7eb 63%); background-size: 400% 100%; animation: cd-shimmer 1.4s ease infinite; }
@keyframes cd-shimmer { 0% { background-position: 100% 50%; } 100% { background-position: 0 50%; } }

.ls { width: 300px; }
.ls-row { display: flex; align-items: center; gap: 12px; padding: 10px 0; border-bottom: 1px solid #f1f5f9; }
.ls-thumb { flex: none; width: 48px; height: 48px; border-radius: 8px; }
.ls-text { flex: 1; }
.ls-line { height: 11px; border-radius: 6px; }
.ls-a { width: 75%; margin-bottom: 8px; }
.ls-b { width: 45%; }
.ls-thumb, .ls-line { background: linear-gradient(90deg, #e5e7eb 25%, #f3f4f6 37%, #e5e7eb 63%); background-size: 400% 100%; animation: ls-shimmer 1.4s ease infinite; }
@keyframes ls-shimmer { 0% { background-position: 100% 50%; } 100% { background-position: 0 50%; } }

.ar { width: 320px; }
.ar-block { margin-bottom: 12px; border-radius: 6px; }
.ar-title { width: 85%; height: 22px; }
.ar-meta { width: 40%; height: 11px; margin-bottom: 16px; }
.ar-hero { height: 110px; margin-bottom: 16px; border-radius: 10px; }
.ar-p { height: 12px; }
.ar-last { width: 60%; }
.ar-block { background: linear-gradient(90deg, #e5e7eb 25%, #f3f4f6 37%, #e5e7eb 63%); background-size: 400% 100%; animation: ar-shimmer 1.4s ease infinite; }
@keyframes ar-shimmer { 0% { background-position: 100% 50%; } 100% { background-position: 0 50%; } }

.tb { width: 340px; border: 1px solid #e5e7eb; border-radius: 10px; overflow: hidden; background: #fff; }
.tb-row { display: grid; grid-template-columns: 1.4fr 1fr 0.8fr; gap: 14px; padding: 12px 14px; border-bottom: 1px solid #f1f5f9; }
.tb-head { background: #f9fafb; }
.tb-cell { display: block; height: 11px; border-radius: 6px; background: linear-gradient(90deg, #e5e7eb 25%, #f3f4f6 37%, #e5e7eb 63%); background-size: 400% 100%; animation: tb-shimmer 1.4s ease infinite; }
@keyframes tb-shimmer { 0% { background-position: 100% 50%; } 100% { background-position: 0 50%; } }

.pf { position: relative; width: 280px; padding-bottom: 18px; overflow: hidden; background: #fff; border: 1px solid #e5e7eb; border-radius: 14px; text-align: center; }
.pf-banner { height: 80px; }
.pf-avatar { width: 64px; height: 64px; margin: -32px auto 12px; border: 4px solid #fff; border-radius: 50%; }
.pf-name { width: 40%; height: 14px; margin: 0 auto 10px; border-radius: 6px; }
.pf-bio { width: 70%; height: 11px; margin: 0 auto 16px; border-radius: 6px; }
.pf-stats { display: flex; justify-content: center; gap: 12px; }
.pf-stats span { width: 50px; height: 24px; border-radius: 6px; background: linear-gradient(90deg, #e5e7eb 25%, #f3f4f6 37%, #e5e7eb 63%); background-size: 400% 100%; animation: pf-shimmer 1.4s ease infinite; }
.pf-banner, .pf-avatar, .pf-name, .pf-bio { background: linear-gradient(90deg, #e5e7eb 25%, #f3f4f6 37%, #e5e7eb 63%); background-size: 400% 100%; animation: pf-shimmer 1.4s ease infinite; }
@keyframes pf-shimmer { 0% { background-position: 100% 50%; } 100% { background-position: 0 50%; } }

.ig { display: grid; grid-template-columns: repeat(2, 140px); gap: 14px; }
.ig-img { height: 100px; margin-bottom: 8px; border-radius: 10px; }
.ig-cap { width: 70%; height: 11px; border-radius: 6px; }
.ig-img, .ig-cap { background: linear-gradient(90deg, #e5e7eb 25%, #f3f4f6 37%, #e5e7eb 63%); background-size: 400% 100%; animation: ig-shimmer 1.4s ease infinite; }
@keyframes ig-shimmer { 0% { background-position: 100% 50%; } 100% { background-position: 0 50%; } }
